var SZE, HUE;

function setup() {
	createCanvas(windowWidth, windowHeight);
	describe("grid of city blocks combining pattern");
	frameRate(30);

	colorMode(HSB);
	HUE = ~~random(360);
	noStroke();

	SZE = ~~random(75, 250);
}

function draw() {
	background(HUE, 75, 10);
	translate(-noise(width+SZE)*(width%SZE), -noise(height+SZE)*(height%SZE));

	for (y = 0; y < height+SZE; y += SZE) {
		for (x = 0; x < width+SZE; x += SZE) {
			drawTile(x, y, SZE);
		}		
	}
}

function drawTile(xx, yy, sz) {
	const _sf = 0.15; // street factor of cell size
	const _x = ~~(xx+sz*_sf); // offset x + y
	const _y = ~~(yy+sz*_sf);
	const s = ~~(sz*(1-_sf)); // reduce size for block, rest street

	// ground
	const H = (HUE + (noise(xx, yy)-0.5) * 90) % 360; // per cell some hue deviation
	fill(H, 50, 25);
	rect(_x, _y, s)

	// buildings
	for (i=~~(noise(xx, yy)*4.2+0.4); i--;) {
		fill(H, 10 + ~~(noise(xx+i, yy)*10), 40 + ~~(noise(yy, xx+i)*10));
		const x = ~~((noise((xx+i)*31, yy) * 0.2 +0.1)*s); // ~~random(s*0.1, s*0.3);
		const y = ~~((noise((yy+i)*17, xx) * 0.2 +0.1)*s); // ~~random(s*0.1,s*0.3);
		const w = ~~((noise(xx, yy+i) * 0.2 +0.7)*(s-x)); // ~~random((s-x)*0.7, (s-x)*0.9);
		const h = ~~((noise(yy, xx+i) * 0.2 +0.7)*(s-y)); // ~~random((s-y)*0.7, (s-x)*0.9);
		rect(_x+x, _y+y, w, h);
	}

	// cars
	const F = frameCount;
	fill(H, 10, 90);
	for (i=~~(noise(xx*0.123-9,yy*0.321)*2.8+0.5);i--;) dir=Math.sign(noise(yy-i,xx+i)-0.5),rect((xx+~~(F/width+1)*width+F*dir+~~(noise(xx+i*12.3, yy+i*32.1)*s))%width, yy+sz*(0.5+0.15*dir)*_sf, min(8, ~~(s*0.1)), 2);
	for (i=~~(noise(yy*0.123,xx*0.321+7)*2.8+0.5);i--;) dir=Math.sign(noise(xx+i,yy-i)-0.5),rect(xx+sz*(0.5-0.15*dir)*_sf, (yy+~~(F/height+1)*height+F*dir+~~(noise(yy-i-12.3, xx-i*32.1)*s))%height, 2, min(8, ~~(s*0.1)));
	// for (i=~~random(3.3);i--;) rect(xx+~~random(s), yy+~~(~~random(1,3)*0.3*sz*_sf), min(8, ~~(s*0.1)), 2);
	// for (i=~~random(3.3);i--;) rect(xx+~~(~~random(1,3)*0.3*sz*_sf), yy+~~random(s), 2, min(8, ~~(s*0.1)));
}

function mousePressed() {
	if (mouseButton === LEFT) setup();
}
